import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, RenderElement } from 'claude-code'

import type {
  GoalpostCategory,
  GoalpostDecision,
  GoalpostEntry,
  GoalpostException,
  GoalpostFinding,
} from '../types'
import { applyEdit, categoryOf, importTarget, inspectChange, inspectCommand } from './detect'
import type { DetectOptions } from './detect'

const PANE = 'goalposts'
const KEEP = 100
const STORE_KEY = 'exceptions'
const TRAILERS = 10

// Anthropic's palette: clay for what was held, olive for what was let through,
// sky for standing exceptions, stone for everything secondary.
const CLAY = '#d97757'
const OLIVE = '#788c5d'
const SKY = '#6a9bcc'
const STONE = '#b0aea5'

const ledger = atom({ plugin: 'goalpost-guard', key: 'ledger' } as const, [])
const exceptions = atom({ plugin: 'goalpost-guard', key: 'exceptions' } as const, [])
const tab = atom({ plugin: 'goalpost-guard', key: 'tab' } as const, 'ledger')
const muted = atom({ plugin: 'goalpost-guard', key: 'muted' } as const, [])
const isPaused = atom({ plugin: 'goalpost-guard', key: 'isPaused' } as const, false)

type Mode = 'ask' | 'deny' | 'warn' | 'off'
type Configured = Mode | 'inherit'

const MODES: readonly Configured[] = ['inherit', 'ask', 'deny', 'warn', 'off']
const CATEGORIES: readonly GoalpostCategory[] = ['tests', 'suppressions', 'config', 'ci', 'coverage', 'bypass']

const CATEGORY_LABEL: Record<GoalpostCategory, string> = {
  tests: 'Tests: assertions, skips, .only, deleted tests, snapshots',
  suppressions: 'Suppressions: @ts-ignore, eslint-disable, noqa…',
  config: 'Config: tsconfig strictness, lint rules, mypy, ruff',
  ci: 'CI: continue-on-error, || true, removed checks and hooks',
  coverage: 'Coverage thresholds',
  bypass: 'Skipped git hooks: --no-verify, HUSKY=0, SKIP=',
}

const DECISION_LOOK: Record<GoalpostDecision, { label: string; color: string }> = {
  blocked: { label: 'HELD', color: CLAY },
  allowed: { label: 'ALLOWED', color: OLIVE },
  excepted: { label: 'EXCEPTION', color: SKY },
  warned: { label: 'NOTED', color: STONE },
}

const ANSWER = {
  block: 'Block it',
  once: 'Allow once',
  file: 'Allow in this file',
  project: 'Allow in this project',
} as const

type Settings = {
  mode: Configured
  categories: ReadonlySet<GoalpostCategory>
  testPattern?: RegExp
  ignore: readonly RegExp[]
  headless: 'deny' | 'allow'
  isTrailerOn: boolean
}

type Verdict = { kind: 'pass' } | { kind: 'warn'; note: string } | { kind: 'deny'; reason: string }

// ---------------------------------------------------------------- settings

function settingsOf(options: Record<string, unknown>): Settings {
  const mode = MODES.find(one => one === options.mode) ?? 'inherit'
  const categories = new Set(CATEGORIES.filter(category => options[category] !== false))
  let testPattern: RegExp | undefined
  if (typeof options.testPattern === 'string' && options.testPattern !== '') {
    try {
      testPattern = new RegExp(options.testPattern)
    } catch {
      testPattern = undefined
    }
  }
  const globs = Array.isArray(options.ignorePaths) ? options.ignorePaths : []

  return {
    mode,
    categories,
    testPattern,
    ignore: globs.filter((glob): glob is string => typeof glob === 'string' && glob !== '').map(globToRegExp),
    headless: options.headless === 'allow' ? 'allow' : 'deny',
    isTrailerOn: options.commitTrailer !== false,
  }
}

// One pass, longest token first, so `**/` never reads as `*` twice and no placeholder is needed.
const GLOB_TOKENS: Record<string, string> = { '**/': '(?:.*/)?', '**': '.*', '*': '[^/]*', '?': '[^/]' }

function globToRegExp(glob: string): RegExp {
  const body = glob
    .replace(/^\.\//, '')
    .replace(/\/+$/, '')
    .replace(/\*\*\/|\*\*|\*|\?|[.+^${}()|[\]\\]/g, token => GLOB_TOKENS[token] ?? `\\${token}`)

  return new RegExp(`(?:^|/)${body}(?:/.*)?$`)
}

function relative(path: string, cwd: string): string {
  return path.startsWith(`${cwd}/`) ? path.slice(cwd.length + 1) : path
}

async function detectOptions($: EngineInterface, settings: Settings): Promise<DetectOptions> {
  const off = new Set(await read($, muted))

  return {
    categories: new Set([...settings.categories].filter(category => !off.has(category))),
    testPattern: settings.testPattern,
  }
}

/**
 * The EMCC profile, or null when emcc-core is not installed. `profile()` is
 * `off` while EMCC is halted, so the kill switch reaches this mod too.
 */
async function emccProfile($: EngineInterface): Promise<'standard' | 'strict' | 'off' | null> {
  try {
    return await $.emcc.profile()
  } catch {
    return null
  }
}

async function modeOf($: EngineInterface, configured: Configured): Promise<Mode> {
  if (await read($, isPaused)) {
    return 'off'
  }
  const profile = await emccProfile($)
  if (profile === 'off') {
    return 'off'
  }
  if (configured !== 'inherit') {
    return configured
  }

  if (profile === 'strict') {
    return 'deny'
  }

  // standard reports instead of asking when someone can read the report: witness shows the flag on the step
  return profile === 'standard' && (await $.session.surfaces()).length > 0 ? 'warn' : 'ask'
}

// ---------------------------------------------------------------- ledger, badge, exceptions

function summary(findings: readonly GoalpostFinding[], cwd: string): string {
  return findings.map(finding => `${finding.file ? `${relative(finding.file, cwd)} ` : ''}${finding.title}`).join('; ')
}

async function record(
  $: EngineInterface,
  tool: string,
  id: string,
  findings: readonly GoalpostFinding[],
  decision: GoalpostDecision,
  note?: string,
): Promise<void> {
  if (findings.length === 0) {
    return
  }
  const at = await $.clock.now()
  const entries: GoalpostEntry[] = findings.map((finding, index) => ({
    id: `${id}:${index}`,
    at,
    tool,
    finding,
    decision,
    ...(note === undefined ? {} : { note }),
  }))
  await update($, ledger, list => [...list, ...entries].slice(-KEEP))
  await refreshBadge($)
  // Only a bar that was lowered is flagged: a held change lowered nothing, and the ledger already shows it.
  if (decision === 'blocked') {
    return
  }
  for (const finding of findings) {
    try {
      await $.emcc.flag({
        source: 'goalpost-guard',
        rule: finding.rule,
        ...(finding.file === undefined ? {} : { file: finding.file }),
        text: `${finding.title} (${TRAILER_WORDS[decision]})`,
      })
    } catch {
      // emcc-core is not installed, or is older than 0.2.0: nothing to tell.
    }
  }
}

async function refreshBadge($: EngineInterface): Promise<void> {
  const list = await read($, ledger)
  const held = list.filter(entry => entry.decision === 'blocked').length
  const through = list.filter(entry => entry.decision !== 'blocked').length
  const parts = [held > 0 ? `${held} held` : '', through > 0 ? `${through} let through` : ''].filter(Boolean)
  try {
    await $.emcc.badge({
      id: 'goalpost-guard',
      text: parts.length > 0 ? `goalposts: ${parts.join(', ')}` : undefined,
      tone: through > 0 ? 'warn' : 'good',
    })
  } catch {
    // emcc-core is not installed: this mod draws its own line instead.
  }
}

function isCovered(exception: GoalpostException, finding: GoalpostFinding, project: string): boolean {
  return (
    exception.project === project &&
    exception.rule === finding.rule &&
    (exception.file === undefined || exception.file === finding.file)
  )
}

async function storedExceptions($: EngineInterface): Promise<GoalpostException[]> {
  const value = await $.store.get(STORE_KEY)

  return Array.isArray(value) ? (value as GoalpostException[]) : []
}

async function addExceptions(
  $: EngineInterface,
  findings: readonly GoalpostFinding[],
  scope: 'file' | 'project',
  note: string,
): Promise<void> {
  const project = await $.session.cwd()
  const at = await $.clock.now()
  const added: GoalpostException[] = findings.map(finding => ({
    project,
    rule: finding.rule,
    ...(scope === 'file' && finding.file !== undefined ? { file: finding.file } : {}),
    note,
    at,
  }))
  const kept = (await storedExceptions($)).filter(old => !added.some(one => sameException(one, old)))
  await $.store.set(STORE_KEY, [...kept, ...added])
  await update($, exceptions, () => [...kept, ...added].filter(one => one.project === project))
}

function sameException(a: GoalpostException, b: GoalpostException): boolean {
  return a.project === b.project && a.rule === b.rule && a.file === b.file
}

async function revokeException($: EngineInterface, gone: GoalpostException): Promise<void> {
  const kept = (await storedExceptions($)).filter(one => !sameException(one, gone))
  await $.store.set(STORE_KEY, kept)
  await update($, exceptions, list => list.filter(one => !sameException(one, gone)))
}

// ---------------------------------------------------------------- the gate

async function decide(
  $: EngineInterface,
  tool: string,
  id: string,
  found: readonly GoalpostFinding[],
  settings: Settings,
  mode: Mode,
): Promise<Verdict> {
  const cwd = await $.session.cwd()
  const watched = found.filter(
    finding => finding.file === undefined || !settings.ignore.some(glob => glob.test(relative(finding.file ?? '', cwd))),
  )
  const standing = await storedExceptions($)
  const excepted = watched.filter(finding => standing.some(one => isCovered(one, finding, cwd)))
  const open = watched.filter(finding => !excepted.includes(finding))
  await record($, tool, id, excepted, 'excepted')
  if (open.length === 0) {
    return { kind: 'pass' }
  }
  const what = summary(open, cwd)

  if (mode === 'warn') {
    await record($, tool, id, open, 'warned')

    return { kind: 'warn', note: `goalpost-guard noted that this change ${what}. Say so to the user in your summary.` }
  }
  if (mode === 'deny') {
    await record($, tool, id, open, 'blocked')

    return {
      kind: 'deny',
      reason:
        `goalpost-guard refused this change: it ${what}. ` +
        'This session does not let a check pass by lowering the bar. Fix the code instead, or ask the user to allow it.',
    }
  }
  if ((await $.session.surfaces()).length === 0) {
    if (settings.headless === 'allow') {
      await record($, tool, id, open, 'warned', 'no one could be asked')

      return { kind: 'warn', note: `goalpost-guard let this through unasked (no screen): it ${what}. Report it.` }
    }
    await record($, tool, id, open, 'blocked', 'no one could be asked')

    return {
      kind: 'deny',
      reason: `goalpost-guard held this change: it ${what}, and no one is here to allow it. Make the check pass without lowering the bar.`,
    }
  }

  const answer = await $.ui
    .ask(`Goalpost Guard: this ${tool === 'Bash' ? 'command' : 'change'} ${what}. Allow it?`, {
      header: 'Goalpost',
      options: [ANSWER.block, ANSWER.once, ANSWER.file, ANSWER.project],
    })
    .catch(() => ANSWER.block)

  if (answer === ANSWER.once) {
    await record($, tool, id, open, 'allowed')

    return { kind: 'pass' }
  }
  if (answer === ANSWER.file || answer === ANSWER.project) {
    await addExceptions($, open, answer === ANSWER.file ? 'file' : 'project', `allowed from the dialog: ${what}`)
    await record($, tool, id, open, 'allowed', answer === ANSWER.file ? 'from now on in this file' : 'from now on in this project')

    return { kind: 'pass' }
  }
  const said = answer === ANSWER.block ? undefined : answer.trim()
  await record($, tool, id, open, 'blocked', said)

  return {
    kind: 'deny',
    reason:
      `goalpost-guard held this change: it ${what}. The user blocked it. ` +
      (said ? `The user says: "${said}"` : 'Make the check pass without lowering the bar, or explain why the bar has to move.'),
  }
}

function normalized(path: string): string {
  const parts: string[] = []
  for (const part of path.split('/')) {
    if (part === '..') {
      parts.pop()
    } else if (part !== '.' && part !== '') {
      parts.push(part)
    }
  }

  return `/${parts.join('/')}`
}

/** Where a module an import names could be on disk, relative to the file importing it. */
function candidatesFor(file: string, target: string, cwd: string): string[] | null {
  const dir = file.slice(0, file.lastIndexOf('/')) || cwd
  if (target.startsWith('.') && target.includes('/')) {
    const base = normalized(`${dir.startsWith('/') ? dir : `${cwd}/${dir}`}/${target}`)

    return ['', '.js', '.ts', '.tsx', '.jsx', '.mjs', '.cjs', '/index.js', '/index.ts'].map(ext => `${base}${ext}`)
  }
  if (/^\.+\w/.test(target) || /^\w+(?:\.\w+)+$/.test(target)) {
    const ups = target.match(/^\.*/)?.[0].length ?? 0
    const root = ups === 0 ? cwd : normalized(`${dir.startsWith('/') ? dir : `${cwd}/${dir}`}${'/..'.repeat(Math.max(0, ups - 1))}`)
    const base = `${root}/${target.slice(ups).replace(/\./g, '/')}`

    return [`${base}.py`, `${base}/__init__.py`]
  }

  return null
}

/**
 * Keeps a retargeted import only when the module the test used to load is
 * still on disk: then the test was pointed away from real code. When it is
 * gone, the code moved and the import followed it.
 */
async function withRealRetargets($: EngineInterface, found: GoalpostFinding[]): Promise<GoalpostFinding[]> {
  const cwd = await $.session.cwd()
  const kept: GoalpostFinding[] = []
  for (const finding of found) {
    const old = finding.rule === 'tests.retargeted' ? importTarget(finding.before?.[0] ?? '')?.target : undefined
    const places = old === undefined || finding.file === undefined ? null : candidatesFor(finding.file, old, cwd)
    if (places === null) {
      kept.push(finding)
      continue
    }
    let isThere = false
    for (const place of places) {
      if (await $.fs.exists(place)) {
        isThere = true
        break
      }
    }
    if (isThere) {
      kept.push(finding)
    }
  }

  return kept
}

async function fileFindings(
  $: EngineInterface,
  path: string,
  toAfter: (before: string | null) => string | null | undefined,
  options: DetectOptions,
): Promise<GoalpostFinding[]> {
  const before = (await $.fs.exists(path)) ? await $.fs.read(path) : null
  const after = toAfter(before)
  if (after === undefined) {
    return []
  }

  return withRealRetargets($, inspectChange({ path, before, after }, options))
}

function heldForError(error: unknown): Verdict {
  const why = error instanceof Error ? error.message : String(error)

  return {
    kind: 'deny',
    reason: `goalpost-guard could not check this change (${why.slice(0, 200)}), so it held it. The user can run /goalposts pause to let changes through.`,
  }
}

// ---------------------------------------------------------------- commit trailers

const COMMIT = /\bgit\b(?:\s+-[cC]\s+\S+)*\s+commit\b/g
const AMEND = /\bgit\b(?:\s+-[cC]\s+\S+)*\s+commit\b[^;&|]*\s--amend\b/

function quoted(text: string): string {
  return `'${text.replace(/'/g, `'\\''`)}'`
}

const TRAILER_WORDS: Record<GoalpostDecision, string> = {
  blocked: 'held',
  allowed: 'allowed by the user',
  excepted: 'standing exception',
  warned: 'let through and reported',
}

function trailerOf(entry: GoalpostEntry, cwd: string): string {
  const where = entry.finding.file ? `${relative(entry.finding.file, cwd)}: ` : ''
  const why = entry.note ? `: ${entry.note}` : ''

  return `Goalpost-Change: ${where}${entry.finding.title} (${TRAILER_WORDS[entry.decision]}${why})`.replace(/\s+/g, ' ').slice(0, 240)
}

/** The command with `--trailer` lines after its first `git commit` outside quotes, or null without one. */
function withTrailers(command: string, entries: readonly GoalpostEntry[], cwd: string): string | null {
  const quotedSpans = [...command.matchAll(/'[^']*'|"(?:\\.|[^"\\])*"/g)].map(match => [match.index, match.index + match[0].length])
  for (const match of command.matchAll(COMMIT)) {
    const at = match.index
    if (quotedSpans.some(([from = 0, to = 0]) => at > from && at < to)) {
      continue
    }
    const end = at + match[0].length
    const flags = entries.map(entry => ` --trailer ${quoted(trailerOf(entry, cwd))}`).join('')

    return command.slice(0, end) + flags + command.slice(end)
  }

  return null
}

// ---------------------------------------------------------------- audit

async function audit($: EngineInterface, base: string, options: DetectOptions): Promise<string> {
  const listed = await $.process.run(['git', 'diff', '--name-status', '-M', base])
  if (listed.exitCode !== 0) {
    return `git diff ${base} failed: ${listed.stderr.trim().slice(0, 200)}`
  }
  const untracked = await $.process.run(['git', 'ls-files', '--others', '--exclude-standard'])
  const rows = listed.stdout
    .split('\n')
    .filter(Boolean)
    .map(line => line.split('\t'))
  for (const path of untracked.stdout.split('\n').filter(Boolean)) {
    rows.push(['A', path])
  }
  const cwd = await $.session.cwd()
  const found: GoalpostFinding[] = []
  for (const [status = '', first = '', second] of rows.slice(0, 300)) {
    const path = `${cwd}/${second ?? first}`
    const shown = await $.process.run(['git', 'show', `${base}:${first}`])
    const before = status.startsWith('A') || shown.exitCode !== 0 ? null : shown.stdout
    const after = status.startsWith('D') || !(await $.fs.exists(path)) ? null : await $.fs.read(path)
    found.push(...(await withRealRetargets($, inspectChange({ path, before, after }, options))))
  }
  if (found.length === 0) {
    return `Nothing in the changes since ${base} lowers the bar (${rows.length} files checked).`
  }

  return [
    `${found.length} ${found.length === 1 ? 'change lowers' : 'changes lower'} the bar since ${base}:`,
    ...found.map(finding => `- ${relative(finding.file ?? '', cwd)} ${finding.title}: ${finding.detail}`),
  ].join('\n')
}

// ---------------------------------------------------------------- register

export const register: Register = (on, options) => {
  const settings = settingsOf(options as Record<string, unknown>)

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'goalposts',
      description: 'Goalpost Guard: open the ledger, or "audit [ref]", "pause", "resume"',
    })
    const project = await $.session.cwd()
    const standing = (await storedExceptions($)).filter(one => one.project === project)
    await update($, exceptions, () => standing)

    return next(e)
  })

  on('command.run', { command: 'goalposts' }, async ($, e) => {
    const [verb = '', ...rest] = e.args.trim().split(/\s+/)
    if (verb === 'pause' || verb === 'resume') {
      await update($, isPaused, () => verb === 'pause')

      return { text: verb === 'pause' ? 'Goalpost Guard paused for this session.' : 'Goalpost Guard is on again.' }
    }
    if (verb === 'audit') {
      return { text: await audit($, rest[0] ?? 'HEAD', await detectOptions($, settings)) }
    }
    const opened = await $.ui.open({ id: PANE, title: 'Goalpost Guard', focus: true, closeOnEscape: true })
    if (!opened.isPlaced) {
      const list = await read($, ledger)

      return {
        text:
          list.length === 0
            ? 'Goalpost Guard has not held anything this session.'
            : list.map(entry => `${DECISION_LOOK[entry.decision].label} ${entry.finding.title} ${entry.finding.file ?? ''}`).join('\n'),
      }
    }

    return { text: 'Goalpost Guard ledger opened.' }
  })

  on('tool.call', { tool: 'Edit' }, async ($, e, next) => {
    const mode = await modeOf($, settings.mode)
    if (mode === 'off') {
      return next(e)
    }
    let verdict: Verdict
    try {
      const found = await fileFindings(
        $,
        e.file_path,
        before => (before === null ? undefined : (applyEdit(before, e.old_string, e.new_string, e.replace_all === true) ?? undefined)),
        await detectOptions($, settings),
      )
      verdict = await decide($, 'Edit', e.tool_use_id, found, settings, mode)
    } catch (error) {
      verdict = heldForError(error)
    }
    if (verdict.kind === 'deny') {
      return { deny: verdict.reason }
    }
    const ran = await next(e)
    if (verdict.kind === 'warn' && ran.deny === undefined) {
      return { ...ran, context: [...(ran.context ?? []), verdict.note] }
    }

    return ran
  })

  on('tool.call', { tool: 'Write' }, async ($, e, next) => {
    const mode = await modeOf($, settings.mode)
    if (mode === 'off') {
      return next(e)
    }
    let verdict: Verdict
    try {
      const found = await fileFindings($, e.file_path, () => e.content, await detectOptions($, settings))
      verdict = await decide($, 'Write', e.tool_use_id, found, settings, mode)
    } catch (error) {
      verdict = heldForError(error)
    }
    if (verdict.kind === 'deny') {
      return { deny: verdict.reason }
    }
    const ran = await next(e)
    if (verdict.kind === 'warn' && ran.deny === undefined) {
      return { ...ran, context: [...(ran.context ?? []), verdict.note] }
    }

    return ran
  })

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const mode = await modeOf($, settings.mode)
    if (mode === 'off') {
      return next(e)
    }
    let verdict: Verdict
    try {
      const found = inspectCommand(e.command, await detectOptions($, settings))
      verdict = await decide($, 'Bash', e.tool_use_id, found, settings, mode)
    } catch (error) {
      verdict = heldForError(error)
    }
    if (verdict.kind === 'deny') {
      return { deny: verdict.reason }
    }

    const cwd = await $.session.cwd()
    const listed = settings.isTrailerOn ? await read($, ledger) : []
    const pending = listed.filter(entry => entry.decision !== 'blocked' && entry.reportedAt === undefined)
    // An amend rewrites the last commit's message: carry that commit's trailers over to it.
    const lastAt = Math.max(-1, ...listed.map(entry => entry.reportedAt ?? -1))
    const again = AMEND.test(e.command) && lastAt >= 0 ? listed.filter(entry => entry.reportedAt === lastAt) : []
    const reported = [...again, ...pending].slice(-TRAILERS)
    const rewritten = reported.length > 0 ? withTrailers(e.command, reported, cwd) : null
    const ran = await next(rewritten === null ? e : { ...e, command: rewritten })
    if (rewritten !== null && ran.deny === undefined && ran.isError !== true) {
      const done = new Set(reported.map(entry => entry.id))
      const at = await $.clock.now()
      await update($, ledger, list => list.map(entry => (done.has(entry.id) ? { ...entry, reportedAt: at } : entry)))
    }
    if (verdict.kind === 'warn' && ran.deny === undefined) {
      return { ...ran, context: [...(ran.context ?? []), verdict.note] }
    }

    return ran
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || (await emccProfile($)) !== null) {
      return next(e)
    }
    const list = await read($, ledger)
    const paused = await read($, isPaused)
    if (list.length === 0 && !paused) {
      return next(e)
    }
    const held = list.filter(entry => entry.decision === 'blocked').length
    const through = list.length - held
    // What draws beneath (another plugin's band, or the engine's) keeps the rows the guard's one row leaves.
    const below = await next({ ...e, props: { ...e.props, maxRows: Math.max(1, e.props.maxRows - 1) } })
    const { Box, Button, Text } = $.ui.resolve(e)

    const row = (
      <Box>
        <Text color={CLAY} bold>
          Goalpost Guard{' '}
        </Text>
        {paused && <Text color={STONE}>paused </Text>}
        {held > 0 && <Text color={CLAY}>{held} held </Text>}
        {through > 0 && <Text color={OLIVE}>{through} let through </Text>}
        <Button key="ledger" label="Ledger" onPress={() => $.ui.open({ id: PANE, title: 'Goalpost Guard', focus: true, closeOnEscape: true })} />
      </Box>
    )
    if (isBlank(below)) {
      return row
    }

    return (
      <Box flexDirection="column">
        {row}
        {below}
      </Box>
    )
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Button, Text } = $.ui.resolve(e)
    const shown = await read($, tab)
    const list = await read($, ledger)
    const standing = await read($, exceptions)
    const off = await read($, muted)
    const paused = await read($, isPaused)
    const mode = await modeOf($, settings.mode)
    const cwd = await $.session.cwd()
    const held = list.filter(entry => entry.decision === 'blocked').length
    const room = Math.max(3, Math.floor(((e.viewport?.rows ?? 24) - 6) / 4))

    const tabs = (
      <Box gap={1}>
        <Button key="tab-ledger" hotkey="1" label={`Ledger ${list.length}`} variant={shown === 'ledger' ? 'primary' : undefined} onPress={() => update($, tab, () => 'ledger')} />
        <Button key="tab-exceptions" hotkey="2" label={`Exceptions ${standing.length}`} variant={shown === 'exceptions' ? 'primary' : undefined} onPress={() => update($, tab, () => 'exceptions')} />
        <Button key="tab-rules" hotkey="3" label="Rules" variant={shown === 'rules' ? 'primary' : undefined} onPress={() => update($, tab, () => 'rules')} />
        <Button key="pause" hotkey="p" label={paused ? 'Resume' : 'Pause'} onPress={() => update($, isPaused, value => !value)} />
      </Box>
    )
    const status = (
      <Text>
        <Text color={STONE}>mode </Text>
        <Text color={mode === 'off' ? STONE : CLAY} bold>
          {mode}
        </Text>
        <Text color={STONE}>
          {settings.mode === 'inherit' && mode !== 'off' ? ' (inherited)' : ''}
          {'   '}
          {held} held, {list.length - held} let through
        </Text>
      </Text>
    )

    if (shown === 'exceptions') {
      return (
        <Box flexDirection="column" gap={1}>
          {tabs}
          {status}
          {standing.length === 0 && <Text color={STONE}>No standing exceptions in this project.</Text>}
          {standing.map(one => (
            <Box key={`exception-${one.rule}-${one.file ?? '*'}`} flexDirection="column">
              <Text>
                <Text color={SKY} bold>
                  {one.rule}
                </Text>
                <Text> {one.file ? relative(one.file, cwd) : 'anywhere in this project'}</Text>
              </Text>
              <Text color={STONE}>{one.note}</Text>
              <Button key={`revoke-${one.rule}-${one.file ?? '*'}`} label="Revoke" onPress={() => revokeException($, one)} />
            </Box>
          ))}
        </Box>
      )
    }

    if (shown === 'rules') {
      return (
        <Box flexDirection="column" gap={1}>
          {tabs}
          {status}
          {CATEGORIES.map(category => {
            const isConfigured = settings.categories.has(category)
            const isOn = isConfigured && !off.includes(category)

            return (
              <Box key={`rule-${category}`} gap={1}>
                <Box width={10} flexShrink={0}>
                  {isConfigured ? (
                    <Button
                      key={`toggle-${category}`}
                      label={isOn ? 'Mute' : 'Unmute'}
                      onPress={() => update($, muted, now => (now.includes(category) ? now.filter(one => one !== category) : [...now, category]))}
                    />
                  ) : (
                    <Text color={STONE}>/config</Text>
                  )}
                </Box>
                <Box width={3} flexShrink={0}>
                  <Text color={isOn ? OLIVE : STONE} bold>
                    {isOn ? 'on' : 'off'}
                  </Text>
                </Box>
                <Box flexGrow={1} flexShrink={1}>
                  <Text color={isOn ? undefined : STONE}>{CATEGORY_LABEL[category]}</Text>
                </Box>
              </Box>
            )
          })}
          <Text color={STONE}>Mute lasts this session; /config changes it for good.</Text>
        </Box>
      )
    }

    return (
      <Box flexDirection="column" gap={1}>
        {tabs}
        {status}
        {list.length === 0 && <Text color={STONE}>Nothing held yet. Changes that lower the bar show up here.</Text>}
        {[...list]
          .reverse()
          .slice(0, room)
          .map(entry => {
            const look = DECISION_LOOK[entry.decision]

            return (
              <Box key={`entry-${entry.id}`} flexDirection="column">
                <Text>
                  <Text color={look.color} bold inverse>
                    {` ${look.label} `}
                  </Text>
                  <Text color={STONE}> {categoryOf(entry.finding)} </Text>
                  <Text>{entry.finding.file ? relative(entry.finding.file, cwd) : entry.tool}</Text>
                </Text>
                <Text bold>{entry.finding.title}</Text>
                {(entry.finding.before ?? []).map(line => (
                  <Text color={CLAY} wrap="truncate-end">
                    {`  - ${line}`}
                  </Text>
                ))}
                {(entry.finding.after ?? []).map(line => (
                  <Text color={SKY} wrap="truncate-end">
                    {`  + ${line}`}
                  </Text>
                ))}
                {entry.note !== undefined && <Text color={STONE} italic>{`  ${entry.note}`}</Text>}
                {entry.decision === 'blocked' && entry.finding.file !== undefined && (
                  <Button
                    key={`allow-${entry.id}`}
                    label="Allow in this file"
                    onPress={() => addExceptions($, [entry.finding], 'file', 'allowed from the ledger')}
                  />
                )}
              </Box>
            )
          })}
      </Box>
    )
  })
}

/** Whether the band beneath drew nothing: no tree, or a Box or Text holding no text and no control. */
function isBlank(tree: RenderElement | null | undefined): boolean {
  if (tree === null || tree === undefined) {
    return true
  }
  if (tree.type !== 'Box' && tree.type !== 'Text') {
    return false
  }

  return (tree.children ?? []).every(child => (typeof child === 'string' ? child === '' : typeof child === 'object' && child !== null && 'type' in child && isBlank(child as RenderElement)))
}

files.hooks/detect.ts:
import type { GoalpostCategory, GoalpostFinding, GoalpostRule } from '../types'

/**
 * What the detectors look at, as the hooks module configured them.
 */
export type DetectOptions = {
  /** The categories that are on; a finding of any other is dropped. */
  categories: ReadonlySet<GoalpostCategory>
  /** An extra pattern for test files, on top of the usual names. */
  testPattern?: RegExp
}

/** One file as it was and as the change leaves it; `null` when it does not exist. */
export type FileChange = { path: string; before: string | null; after: string | null }

const CATEGORY_OF: Record<GoalpostRule, GoalpostCategory> = {
  'tests.assertions': 'tests',
  'tests.removed': 'tests',
  'tests.skipped': 'tests',
  'tests.focused': 'tests',
  'tests.loosened': 'tests',
  'tests.expected': 'tests',
  'tests.retargeted': 'tests',
  'tests.snapshots': 'tests',
  'tests.narrowed': 'tests',
  suppressions: 'suppressions',
  config: 'config',
  ci: 'ci',
  coverage: 'coverage',
  bypass: 'bypass',
  'shell-edit': 'tests',
}

const SAMPLE = 3

// ---------------------------------------------------------------- text helpers

function count(text: string, pattern: RegExp): number {
  return text.match(new RegExp(pattern.source, pattern.flags.includes('g') ? pattern.flags : `${pattern.flags}g`))?.length ?? 0
}

/** The text without whole-line comments, so commenting a line out counts as removing it. */
function code(text: string): string {
  return text
    .split('\n')
    .filter(line => !/^\s*(?:\/\/|#(?![!\[])|\/\*|\*|--|<!--)/.test(line))
    .join('\n')
}

/** The lines of `after` that match `pattern` and were not in `before`, trimmed, at most a few. */
function addedLines(before: string, after: string, global: RegExp): string[] {
  const pattern = new RegExp(global.source, global.flags.replace('g', ''))
  const held = new Map<string, number>()
  for (const line of before.split('\n')) {
    held.set(line.trim(), (held.get(line.trim()) ?? 0) + 1)
  }
  const added: string[] = []
  for (const line of after.split('\n')) {
    const key = line.trim()
    const left = held.get(key) ?? 0
    if (left > 0) {
      held.set(key, left - 1)
    } else if (pattern.test(line)) {
      added.push(key)
    }
  }

  return added.slice(0, SAMPLE)
}

/**
 * Assertion lines rewritten in place: a removed line and an added one that
 * read the same once every number and string is blanked out, as when
 * `toBe(24.19)` becomes `toBe(24)`.
 */
function rewrittenValues(before: string, after: string): Array<readonly [string, string]> {
  const literal = /-?\d+(?:\.\d+)?(?:e-?\d+)?|'(?:\\.|[^'\\])*'|"(?:\\.|[^"\\])*"|`(?:\\.|[^`\\])*`/g
  const shape = (line: string): string => line.replace(literal, '_')
  const single = new RegExp(ASSERTION.source)
  const gone = removedLinesAll(before, after).filter(line => single.test(line))
  const added = removedLinesAll(after, before).filter(line => single.test(line))
  const pairs: Array<readonly [string, string]> = []
  for (const line of gone) {
    const index = added.findIndex(other => shape(other) === shape(line))
    if (index >= 0) {
      pairs.push([line, added[index] ?? ''] as const)
      added.splice(index, 1)
    }
  }

  return pairs
}

const IMPORT_FORMS: readonly RegExp[] = [
  /^(\s*(?:import|export)\b[^'"`]*?\bfrom\s*)(['"`])([^'"`]+)\2/,
  /^(\s*import\s*)(['"`])([^'"`]+)\2/,
  /^(.*?\brequire\s*\(\s*)(['"`])([^'"`]+)\2/,
  /^(\s*from\s+)()([\w.]+)(?=\s+import\b)/,
  /^(\s*import\s+)()([\w.]+)\s*$/,
]

/** The module an import line loads, and the line with that module blanked out. */
export function importTarget(line: string): { target: string; shape: string } | null {
  for (const form of IMPORT_FORMS) {
    const match = form.exec(line)
    if (match) {
      return { target: match[3] ?? '', shape: line.replace(form, (_all, lead: string, quote: string) => `${lead}${quote}_${quote}`) }
    }
  }

  return null
}

/**
 * Imports that now load the same names from a different module: a test
 * pointed at a stand-in instead of the code it was written for. Whether the
 * old module still exists (a stand-in) or was moved (a fix) is the hooks'
 * call, since only they can look at the disk.
 */
function retargetedImports(before: string, after: string): Array<readonly [string, string]> {
  const gone = removedLinesAll(before, after).filter(line => importTarget(line) !== null)
  const added = removedLinesAll(after, before).filter(line => importTarget(line) !== null)
  const pairs: Array<readonly [string, string]> = []
  for (const line of gone) {
    const shape = importTarget(line)?.shape
    const index = added.findIndex(other => importTarget(other)?.shape === shape)
    if (index >= 0) {
      pairs.push([line, added[index] ?? ''] as const)
      added.splice(index, 1)
    }
  }

  return pairs
}

/** The names an import line brings in: `{ a, b as c }`, a default, `* as x`, or Python's `import a, b`. */
function importedNames(line: string): string[] {
  const js = /^\s*import\s+(.+?)\s+from\b/.exec(line) ?? /^\s*(?:const|let|var)\s+(.+?)\s*=\s*require\b/.exec(line)
  const py = /^\s*from\s+[\w.]+\s+import\s+\(?([^)#]+)/.exec(line)
  const list = js?.[1] ?? py?.[1] ?? ''

  return list
    .replace(/[{}()]/g, ',')
    .split(',')
    .map(part => part.trim().split(/\s+as\s+|\s*:\s*/).pop()?.replace(/^\*\s*as\s+/, '').trim() ?? '')
    .filter(name => /^[A-Za-z_$][\w$]*$/.test(name))
}

/**
 * Names a test stopped importing and now defines itself: the code under test
 * swapped for a copy that lives inside the test.
 */
function inlinedStandIns(before: string, after: string): string[] {
  const names = (text: string): Set<string> =>
    new Set(text.split('\n').filter(line => importTarget(line) !== null).flatMap(importedNames))
  // Still imported counts too: in Python a later `def` shadows the import.
  return [...names(before)].filter(name => {
    const defined = new RegExp(`(?:^|\\n)\\s*(?:export\\s+)?(?:(?:const|let|var)\\s+${name}\\s*=|(?:async\\s+)?function\\s*\\*?\\s*${name}\\s*\\(|class\\s+${name}\\b|def\\s+${name}\\s*\\()`)

    return defined.test(after) && !defined.test(before)
  })
}

/** Every line of `before`, trimmed, that is not in `after` (counting repeats). */
function removedLinesAll(before: string, after: string): string[] {
  const held = new Map<string, number>()
  for (const line of after.split('\n')) {
    held.set(line.trim(), (held.get(line.trim()) ?? 0) + 1)
  }
  const removed: string[] = []
  for (const line of before.split('\n')) {
    const key = line.trim()
    const left = held.get(key) ?? 0
    if (left > 0) {
      held.set(key, left - 1)
    } else if (key !== '') {
      removed.push(key)
    }
  }

  return removed
}

/** The lines of `before` that match `pattern` and are gone from `after`. */
function removedLines(before: string, after: string, pattern: RegExp): string[] {
  return addedLines(after, before, pattern)
}

function basename(path: string): string {
  return path.split('/').pop() ?? path
}

function plural(n: number, one: string, many = `${one}s`): string {
  return `${n} ${n === 1 ? one : many}`
}

// ---------------------------------------------------------------- tests

const TEST_PATH = [
  /(?:^|\/)(?:tests?|__tests__|specs?|e2e)\//,
  /\.(?:test|spec|e2e)\.[cm]?[jt]sx?$/,
  /(?:^|\/)test_[^/]*\.py$/,
  /_test\.(?:py|go|exs?)$/,
  /(?:Test|Tests|Spec)\.(?:java|kt|cs|swift|scala)$/,
  /_spec\.rb$/,
  /\.(?:test|spec)\.(?:php|dart)$/,
]

const BACKUP = /\.(?:bak|orig|rej|swp|tmp)$|~$/

export function isTestFile(path: string, extra?: RegExp): boolean {
  if (BACKUP.test(path)) {
    return false
  }

  return TEST_PATH.some(pattern => pattern.test(path)) || (extra?.test(path) ?? false)
}

const ASSERTION =
  /\bexpect\s*\(|\bassert(?:\.\w+|_\w+|[A-Z]\w*)?\s*!?\s*\(|\bassert\s+(?=[^\s(=:])|\.should\b|\bt\.(?:Errorf?|Fatalf?|Fail(?:Now)?)\s*\(|\brequire\.[A-Z]\w*\s*\(|\bXCTAssert\w*\s*\(|\bpytest\.raises\s*\(/g

const TEST_CASE =
  /\b[xf]?(?:it|test|specify)(?:\.(?:skip|only|todo|concurrent|failing|each\s*\(.*?\)))*\s*\(\s*['"`]|\bdef\s+test\w*\s*\(|\bfunc\s+Test\w*\s*\(|#\[(?:tokio::)?test\]|@Test\b|\bfn\s+test_\w*\s*\(/g

const SKIP =
  /\b(?:it|test|describe|context|suite|specify)\.(?:skip|todo)\b|\bx(?:it|describe|test|context|specify)\s*\(|@pytest\.mark\.(?:skip|skipif|xfail)\b|@unittest\.(?:skip|skipIf|skipUnless|expectedFailure)\b|\bpytest\.(?:skip|xfail)\s*\(|\bt\.Skip(?:f|Now)?\s*\(|#\[ignore\b|@(?:Disabled|Ignore)\b|\bpending\s*\(|\bself\.skipTest\s*\(|\bmarkTestSkipped\s*\(/g

const FOCUS = /\b(?:it|test|describe|context|suite|specify)\.only\b|\bf(?:it|describe|context)\s*\(/g

const STRONG =
  /\.(?:toBe|toEqual|toStrictEqual|toHaveBeenCalledWith|toHaveBeenCalledTimes|toThrow|toThrowError|toMatchObject|toContain|toHaveLength|toHaveProperty|toMatchSnapshot|toMatchInlineSnapshot)\s*\(|\bassert(?:Equals?|_eq|_ne|NotEqual|Raises|Is|In|Count(?:Equal)?|DictEqual|ListEqual|AlmostEqual|Same|Throws)\s*!?\s*\(|\bassert\b[^\n]*(?:==|!=|\bin\b|\bis\b)/g

const WEAK =
  /\.(?:toBeTruthy|toBeDefined|toBeFalsy|toBeInstanceOf|toBeCloseTo|toHaveBeenCalled|toBeGreaterThanOrEqual\s*\(\s*0\s*\)|toBeGreaterThan\s*\(\s*-?1\s*\))\s*\(|\.not\.(?:toBeNull|toBeUndefined|toThrow)\s*\(|\bassert(?:True|IsNotNone|IsInstance|Truthy)\s*\(|\bassert\s+\w+(?:\.\w+)*\s*$|\.toMatch\s*\(\s*\/\.\*\/|expect\.anything\s*\(/gm

const SNAPSHOT_FILE = /(?:__snapshots__\/|\.snap$|\.ambr$|__image_snapshots__\/)/

function testFindings(change: FileChange, testPattern?: RegExp): GoalpostFinding[] {
  const { path, before, after } = change
  const isTest = isTestFile(path, testPattern) || /#\[cfg\(test\)\]/.test(before ?? '')
  const found: GoalpostFinding[] = []

  if (SNAPSHOT_FILE.test(path) && before !== null && before !== after) {
    found.push({
      rule: 'tests.snapshots',
      file: path,
      title: after === null ? 'deletes a snapshot' : 'rewrites a snapshot',
      detail: `${basename(path)} is a recorded expectation; changing it by hand makes the test agree with the code`,
    })
  }
  if (!isTest || before === null) {
    if (isTest && after !== null) {
      const skips = count(code(after), SKIP)
      const focus = count(code(after), FOCUS)
      if (skips > 0) {
        found.push({
          rule: 'tests.skipped',
          file: path,
          title: `adds a test file with ${plural(skips, 'skipped test')}`,
          detail: `${addedLines('', after, SKIP).join(' | ')}`,
          after: addedLines('', after, SKIP),
        })
      }
      if (focus > 0) {
        found.push({
          rule: 'tests.focused',
          file: path,
          title: 'adds a focused test (.only)',
          detail: `only the focused tests run, the rest are silently skipped`,
          after: addedLines('', after, FOCUS),
        })
      }
    }

    return found
  }

  const was = code(before)
  const now = code(after ?? '')

  if (after === null) {
    const cases = count(was, TEST_CASE)
    found.push({
      rule: 'tests.removed',
      file: path,
      title: `deletes a test file${cases > 0 ? ` (${plural(cases, 'test')})` : ''}`,
      detail: `the file and its ${plural(count(was, ASSERTION), 'assertion')} go away`,
    })

    return found
  }

  const casesBefore = count(was, TEST_CASE)
  const casesAfter = count(now, TEST_CASE)
  if (casesAfter < casesBefore) {
    found.push({
      rule: 'tests.removed',
      file: path,
      title: `removes ${plural(casesBefore - casesAfter, 'test')}`,
      detail: `${casesBefore} → ${casesAfter} tests`,
      before: removedLines(before, after, TEST_CASE),
    })
  }

  const assertsBefore = count(was, ASSERTION)
  const assertsAfter = count(now, ASSERTION)
  if (assertsAfter < assertsBefore) {
    found.push({
      rule: 'tests.assertions',
      file: path,
      title: `removes ${plural(assertsBefore - assertsAfter, 'assertion')}`,
      detail: `${assertsBefore} → ${assertsAfter} assertions`,
      before: removedLines(before, after, ASSERTION),
    })
  }

  if (count(now, SKIP) > count(was, SKIP)) {
    found.push({
      rule: 'tests.skipped',
      file: path,
      title: `skips ${plural(count(now, SKIP) - count(was, SKIP), 'test')}`,
      detail: `a skipped test still reads as passing`,
      after: addedLines(before, after, SKIP),
    })
  }

  if (count(now, FOCUS) > count(was, FOCUS)) {
    found.push({
      rule: 'tests.focused',
      file: path,
      title: 'focuses a test (.only)',
      detail: `only the focused tests run, the rest are silently skipped`,
      after: addedLines(before, after, FOCUS),
    })
  }

  const rewritten = rewrittenValues(code(before), code(after))
  if (rewritten.length > 0) {
    found.push({
      rule: 'tests.expected',
      file: path,
      title: `changes the values in ${plural(rewritten.length, 'assertion')}`,
      detail: 'an expected value moved; if it moved to what the code returns now, the test checks nothing',
      before: rewritten.slice(0, SAMPLE).map(([was]) => was),
      after: rewritten.slice(0, SAMPLE).map(([, now]) => now),
    })
  }

  const retargeted = retargetedImports(code(before), code(after))
  if (retargeted.length > 0) {
    const [[was = '', is = ''] = []] = retargeted
    found.push({
      rule: 'tests.retargeted',
      file: path,
      title: `points the test at other code (${importTarget(was)?.target ?? '?'} → ${importTarget(is)?.target ?? '?'})`,
      detail: 'the test now checks a different module than before; a stand-in can pass while the real code stays broken',
      before: retargeted.slice(0, SAMPLE).map(([line]) => line),
      after: retargeted.slice(0, SAMPLE).map(([, line]) => line),
    })
  }

  const inlined = inlinedStandIns(code(before), code(after))
  if (inlined.length > 0) {
    found.push({
      rule: 'tests.retargeted',
      file: path,
      title: `replaces the imported ${inlined.slice(0, 2).join(', ')} with a copy inside the test`,
      detail: 'the test now checks its own copy of the code; the copy can pass while the real code stays broken',
      after: addedLines(before, after, new RegExp(`\\b(?:${inlined.join('|')})\\b`)),
    })
  }

  const weakUp = count(now, WEAK) - count(was, WEAK)
  const strongDown = count(was, STRONG) - count(now, STRONG)
  if (weakUp > 0 && strongDown > 0) {
    found.push({
      rule: 'tests.loosened',
      file: path,
      title: `loosens ${plural(Math.min(weakUp, strongDown), 'assertion')}`,
      detail: `exact checks traded for ones that pass on almost anything`,
      before: removedLines(before, after, STRONG),
      after: addedLines(before, after, WEAK),
    })
  }

  return found
}

// ---------------------------------------------------------------- suppressions

const SUPPRESSIONS: ReadonlyArray<readonly [string, RegExp]> = [
  ['@ts-ignore', /@ts-ignore\b/],
  ['@ts-expect-error', /@ts-expect-error\b/],
  ['@ts-nocheck', /@ts-nocheck\b/],
  ['eslint-disable', /eslint-disable(?:-next-line|-line)?\b/],
  ['biome-ignore', /biome-ignore\b/],
  ['oxlint-disable', /oxlint-disable\b/],
  ['# noqa', /#\s*noqa\b/],
  ['# type: ignore', /#\s*type:\s*ignore\b/],
  ['pyright: ignore', /pyright:\s*ignore\b/],
  ['pylint: disable', /pylint:\s*disable\b/],
  ['mypy: ignore-errors', /mypy:\s*ignore-errors\b/],
  ['//nolint', /\/\/\s*nolint\b/],
  ['#[allow(...)]', /#!?\[allow\(/],
  ['@SuppressWarnings', /@SuppressWarnings\b/],
  ['rubocop:disable', /rubocop:disable\b/],
  ['swiftlint:disable', /swiftlint:disable\b/],
  ['NOLINT', /\bNOLINT(?:NEXTLINE|BEGIN)?\b/],
  ['@phpstan-ignore', /@phpstan-ignore/],
  ['@psalm-suppress', /@psalm-suppress\b/],
  ['#pragma warning disable', /#pragma\s+warning\s+disable\b/],
  ['coverage ignore', /(?:istanbul|c8|v8)\s+ignore\b|pragma:\s*no\s*cover\b/],
]

const PROSE = /\.(?:md|mdx|markdown|txt|rst|adoc)$/

function suppressionFindings({ path, before, after }: FileChange): GoalpostFinding[] {
  if (after === null || PROSE.test(path)) {
    return []
  }
  const added: string[] = []
  const lines: string[] = []
  for (const [name, pattern] of SUPPRESSIONS) {
    const more = count(after, pattern) - count(before ?? '', pattern)
    if (more > 0) {
      added.push(more > 1 ? `${more}× ${name}` : name)
      lines.push(...addedLines(before ?? '', after, pattern))
    }
  }
  if (added.length === 0) {
    return []
  }

  return [
    {
      rule: 'suppressions',
      file: path,
      title: `adds ${added.join(', ')}`,
      detail: `the check still runs, it just stops reporting here`,
      after: lines.slice(0, SAMPLE),
    },
  ]
}

// ---------------------------------------------------------------- config

const TS_CONFIG = /(?:^|\/)[jt]sconfig(?:\.[\w-]+)?\.json$/
const TS_STRICT = [
  'strict',
  'noImplicitAny',
  'strictNullChecks',
  'strictFunctionTypes',
  'strictBindCallApply',
  'strictPropertyInitialization',
  'noImplicitThis',
  'useUnknownInCatchVariables',
  'alwaysStrict',
  'noUncheckedIndexedAccess',
  'exactOptionalPropertyTypes',
  'noImplicitReturns',
  'noImplicitOverride',
  'noFallthroughCasesInSwitch',
  'noUnusedLocals',
  'noUnusedParameters',
  'checkJs',
]
const COVERED_BY_STRICT = new Set([
  'noImplicitAny',
  'strictNullChecks',
  'strictFunctionTypes',
  'strictBindCallApply',
  'strictPropertyInitialization',
  'noImplicitThis',
  'useUnknownInCatchVariables',
  'alwaysStrict',
])

function flag(text: string, key: string): boolean | undefined {
  const match = new RegExp(`["']?\\b${key}\\b["']?\\s*[:=]\\s*(true|false|True|False)\\b`).exec(code(text))

  return match ? match[1]?.toLowerCase() === 'true' : undefined
}

const LINT_CONFIG =
  /(?:^|\/)(?:\.eslintrc(?:\.\w+)?|eslint\.config\.[cm]?[jt]s|\.oxlintrc\.json|biome\.jsonc?|\.stylelintrc(?:\.\w+)?|stylelint\.config\.[cm]?js|deno\.jsonc?)$/
const SEVERITY_RANK: Record<string, number> = { error: 2, '2': 2, warn: 1, '1': 1, info: 1, off: 0, '0': 0 }

function severities(text: string): Map<string, number> {
  const found = new Map<string, number>()
  const pattern = /['"]([@\w/.-]+)['"]\s*:\s*\[?\s*['"]?(error|warn|info|off|[012])\b/g
  for (const match of code(text).matchAll(pattern)) {
    const [, rule = '', level = ''] = match
    found.set(rule, SEVERITY_RANK[level] ?? 0)
  }

  return found
}

const PY_CONFIG = /(?:^|\/)(?:pyproject\.toml|setup\.cfg|tox\.ini|ruff\.toml|\.ruff\.toml|\.flake8|mypy\.ini|\.mypy\.ini|\.pylintrc|pylintrc)$/
const PY_STRICT = [
  'strict',
  'disallow_untyped_defs',
  'disallow_incomplete_defs',
  'disallow_any_generics',
  'check_untyped_defs',
  'warn_return_any',
  'no_implicit_optional',
  'strict_optional',
  'warn_unused_ignores',
]
const PY_LOOSE = ['ignore_errors', 'ignore_missing_imports', 'allow_untyped_defs', 'allow_redefinition']

function ignoredCodes(text: string): number {
  let total = 0
  const pattern = /\b(?:extend-ignore|ignore|disable|extend-per-file-ignores|per-file-ignores|ignore-names)\s*=\s*(\[[^\]]*\]|[^\n]*)/g
  for (const match of code(text).matchAll(pattern)) {
    total += count(match[1] ?? '', /\b[A-Z]{1,4}\d{1,4}\b|\b[a-z]+(?:-[a-z]+)+\b/g)
  }

  return total
}

function configFindings({ path, before, after }: FileChange): GoalpostFinding[] {
  if (before === null) {
    return []
  }
  const now = after ?? ''
  const weaker: string[] = []

  if (TS_CONFIG.test(path)) {
    const strictAfter = flag(now, 'strict') === true
    for (const key of TS_STRICT) {
      if (flag(before, key) === true && flag(now, key) !== true && !(strictAfter && COVERED_BY_STRICT.has(key))) {
        weaker.push(`${key} turned off`)
      }
    }
  }

  if (LINT_CONFIG.test(path)) {
    const was = severities(before)
    const is = severities(now)
    for (const [rule, rank] of was) {
      const level = is.get(rule)
      if (rank > 0 && level === undefined) {
        weaker.push(`${rule} removed`)
      } else if (level !== undefined && level < rank) {
        weaker.push(`${rule} ${rank === 2 ? 'error' : 'warn'} → ${level === 1 ? 'warn' : 'off'}`)
      }
    }
  }

  if (PY_CONFIG.test(path)) {
    for (const key of PY_STRICT) {
      if (flag(before, key) === true && flag(now, key) !== true) {
        weaker.push(`${key} turned off`)
      }
    }
    for (const key of PY_LOOSE) {
      if (flag(before, key) !== true && flag(now, key) === true) {
        weaker.push(`${key} turned on`)
      }
    }
    const more = ignoredCodes(now) - ignoredCodes(before)
    if (more > 0) {
      weaker.push(`${plural(more, 'more ignored rule')}`)
    }
  }

  if (after === null && (TS_CONFIG.test(path) || LINT_CONFIG.test(path))) {
    weaker.push('the whole file deleted')
  }

  if (weaker.length === 0) {
    return []
  }

  return [
    {
      rule: 'config',
      file: path,
      title: `relaxes ${basename(path)}`,
      detail: `${weaker.slice(0, 4).join(', ')}${weaker.length > 4 ? `, +${weaker.length - 4} more` : ''}`,
      after: weaker.slice(0, SAMPLE),
    },
  ]
}

// ---------------------------------------------------------------- CI

const CI_FILE =
  /(?:^|\/)(?:\.github\/workflows\/[^/]+\.ya?ml|\.gitlab-ci\.ya?ml|\.circleci\/config\.ya?ml|azure-pipelines\.ya?ml|bitbucket-pipelines\.ya?ml|\.buildkite\/[^/]+\.ya?ml|Jenkinsfile|\.travis\.ya?ml|\.pre-commit-config\.ya?ml|lefthook\.ya?ml|\.husky\/[^/]+)$/

const CHECK_COMMAND =
  /\b(?:(?:npm|pnpm|yarn|bun)\s+(?:run\s+)?(?:test|lint|typecheck|check|build)|vitest|jest|pytest|go\s+(?:test|vet)|cargo\s+(?:test|clippy|check|nextest)|ctest|mocha|playwright\s+test|rspec|phpunit|dotnet\s+test|tsc|mypy|pyright|eslint|ruff|flake8|pylint|biome|golangci-lint|stylelint|prettier\s+--check|pre-commit\s+run|claude\s+plugin\s+(?:test|validate))\b/g

const CI_SOFTENERS: ReadonlyArray<readonly [string, RegExp]> = [
  ['continue-on-error: true', /continue-on-error:\s*true\b/g],
  ['allow_failure: true', /allow_failure:\s*true\b/g],
  ['|| true', /\|\|\s*(?:true|:)\s*(?:$|[;&)])|\|\|\s*exit\s+0\b/gm],
  ['if: false', /\bif:\s*(?:false|\$\{\{\s*false\s*\}\})/g],
  ['set +e', /\bset\s+\+e\b/g],
]

function ciFindings({ path, before, after }: FileChange): GoalpostFinding[] {
  if (before === null || !CI_FILE.test(path)) {
    return []
  }
  const was = code(before)
  const now = code(after ?? '')
  const weaker: string[] = []
  const lines: string[] = []

  for (const [name, pattern] of CI_SOFTENERS) {
    const more = count(now, pattern) - count(was, pattern)
    if (more > 0) {
      weaker.push(more > 1 ? `${more}× ${name}` : name)
      lines.push(...addedLines(before, after ?? '', pattern))
    }
  }
  const checksGone = count(was, CHECK_COMMAND) - count(now, CHECK_COMMAND)
  if (checksGone > 0) {
    weaker.push(`${plural(checksGone, 'check')} removed`)
    lines.push(...removedLines(before, after ?? '', CHECK_COMMAND).map(line => `- ${line}`))
  }
  const hooksGone = count(was, /^\s*-\s+id:/gm) - count(now, /^\s*-\s+id:/gm)
  if (hooksGone > 0) {
    weaker.push(`${plural(hooksGone, 'hook')} removed`)
  }
  if (after === null) {
    weaker.push('the whole file deleted')
  }
  if (weaker.length === 0) {
    return []
  }

  return [
    {
      rule: 'ci',
      file: path,
      title: `weakens ${basename(path)}`,
      detail: `${weaker.join(', ')}`,
      after: lines.slice(0, SAMPLE),
    },
  ]
}

// ---------------------------------------------------------------- coverage

const COVERAGE_FILE =
  /(?:^|\/)(?:package\.json|jest\.config\.[\w.]+|vitest\.config\.[\w.]+|vite\.config\.[\w.]+|vitest\.workspace\.[\w.]+|pyproject\.toml|setup\.cfg|tox\.ini|\.coveragerc|pytest\.ini|codecov\.ya?ml|\.codecov\.ya?ml|\.nycrc(?:\.\w+)?|\.c8rc(?:\.\w+)?|karma\.conf\.[cm]?js|\.simplecov|Makefile|build\.gradle(?:\.kts)?|pom\.xml|\.github\/workflows\/[^/]+\.ya?ml|\.gitlab-ci\.ya?ml)$/

const THRESHOLDS: ReadonlyArray<readonly [string, RegExp]> = [
  ['fail_under', /\bfail_under\s*[=:]\s*(\d+(?:\.\d+)?)/g],
  ['--cov-fail-under', /--cov-fail-under[= ](\d+(?:\.\d+)?)/g],
  ['--fail-under', /(?<!cov)--fail-under[= ](\d+(?:\.\d+)?)/g],
  ['branches', /["']?\bbranches["']?\s*:\s*(-?\d+(?:\.\d+)?)/g],
  ['functions', /["']?\bfunctions["']?\s*:\s*(-?\d+(?:\.\d+)?)/g],
  ['lines', /["']?\blines["']?\s*:\s*(-?\d+(?:\.\d+)?)/g],
  ['statements', /["']?\bstatements["']?\s*:\s*(-?\d+(?:\.\d+)?)/g],
  ['target', /\btarget:\s*(\d+(?:\.\d+)?)%?/g],
  ['minimum_coverage', /\bminimum_coverage\s*\(?\s*(\d+(?:\.\d+)?)/g],
  ['minimum', /<minimum>(\d*\.?\d+)<\/minimum>|\bminimum\s*=\s*(?:BigDecimal\s*\(\s*)?["']?(\d*\.?\d+)/g],
  ['--check-coverage', /--(?:lines|branches|functions|statements)[= ](\d+(?:\.\d+)?)/g],
]

function thresholds(text: string): Map<string, number[]> {
  const found = new Map<string, number[]>()
  for (const [name, pattern] of THRESHOLDS) {
    const values = [...code(text).matchAll(pattern)].map(match => Number(match[1] ?? match[2]))
    if (values.length > 0) {
      found.set(name, values)
    }
  }

  return found
}

function coverageFindings({ path, before, after }: FileChange): GoalpostFinding[] {
  if (before === null || after === null) {
    return []
  }
  if (!COVERAGE_FILE.test(path) && !/coverage|cov-fail|fail_under|codecov/i.test(before)) {
    return []
  }
  const relevant = /coverage|cov-fail|fail_under|codecov|threshold|minimum|jacoco|simplecov/i
  if (!relevant.test(before)) {
    return []
  }
  const was = thresholds(before)
  const is = thresholds(after)
  const lowered: string[] = []
  for (const [name, values] of was) {
    const now = is.get(name) ?? []
    values.forEach((value, index) => {
      const later = now[index]
      if (later === undefined && now.length < values.length) {
        lowered.push(`${name} ${value} removed`)
      } else if (later !== undefined && later < value) {
        lowered.push(`${name} ${value} → ${later}`)
      }
    })
  }
  if (lowered.length === 0) {
    return []
  }

  return [
    {
      rule: 'coverage',
      file: path,
      title: 'lowers a coverage threshold',
      detail: `${lowered.slice(0, 4).join(', ')}`,
      after: lowered.slice(0, SAMPLE),
    },
  ]
}

// ---------------------------------------------------------------- files

/**
 * Everything a change to one file does to lower the bar, in the categories
 * that are on.
 */
export function inspectChange(change: FileChange, options: DetectOptions): GoalpostFinding[] {
  if (change.before === change.after) {
    return []
  }
  const all = [
    ...testFindings(change, options.testPattern),
    ...suppressionFindings(change),
    ...configFindings(change),
    ...ciFindings(change),
    ...coverageFindings(change),
  ]

  return all.filter(finding => options.categories.has(CATEGORY_OF[finding.rule]))
}

/**
 * The file an Edit leaves, or null when `old` is not in it (the tool will
 * refuse the edit itself).
 */
export function applyEdit(before: string, old: string, replacement: string, isAll = false): string | null {
  if (old === '' || !before.includes(old)) {
    return null
  }

  return isAll ? before.split(old).join(replacement) : before.replace(old, () => replacement)
}

// ---------------------------------------------------------------- shell

/** The command with every quoted string emptied, so flags inside a message don't count. */
function withoutQuoted(command: string): string {
  return command.replace(/'[^']*'|"(?:\\.|[^"\\])*"|\$'[^']*'/g, '""').replace(/<<-?\s*['"]?(\w+)['"]?[\s\S]*?\n\1\b/g, '')
}

type Segment = { words: string[]; redirects: string[] }

/**
 * The simple commands of a command line, split at `&&`, `||`, `;`, `|` and
 * newlines, each as its words (quotes taken off, text kept) and the files it
 * redirects output to. Heredoc bodies are text, not commands, so they go.
 */
function segmentsOf(command: string): Segment[] {
  const text = command.replace(/<<-?\s*(['"]?)(\w+)\1[^\n]*\n[\s\S]*?\n\s*\2(?=\s|$)/g, '')
  const tokens = text.match(/'[^']*'|"(?:\\.|[^"\\])*"|&&|\|\||[;|\n]|\d?>>?|[^\s;&|()<>]+/g) ?? []
  const segments: Segment[] = [{ words: [], redirects: [] }]
  let isRedirect = false
  for (const token of tokens) {
    const current = segments[segments.length - 1] ?? { words: [], redirects: [] }
    if (['&&', '||', ';', '|', '\n'].includes(token)) {
      segments.push({ words: [], redirects: [] })
      isRedirect = false
    } else if (/^\d?>>?$/.test(token)) {
      isRedirect = !/^2/.test(token)
    } else {
      const word = token.replace(/^['"]|['"]$/g, '')
      if (isRedirect) {
        current.redirects.push(word)
        isRedirect = false
      } else {
        current.words.push(word)
      }
    }
  }

  return segments.filter(segment => segment.words.length > 0 || segment.redirects.length > 0)
}

/** The words of a simple command without leading `VAR=value`, `sudo`, `command`, `env` or `xargs`. */
function withoutPrefix(words: string[]): string[] {
  let index = 0
  while (index < words.length && (/^\w+=/.test(words[index] ?? '') || ['sudo', 'command', 'env', 'xargs', 'nohup', 'time'].includes(words[index] ?? ''))) {
    index += 1
  }

  return words.slice(index)
}

const GIT_VERB = (verb: string): RegExp => new RegExp(`\\bgit\\b(?:\\s+-[cC]\\s+\\S+)*\\s+${verb}\\b[^;&|]*`, 'g')

const SKIP_HOOK_ENV = /(?:^|[\s;&|(])(?:export\s+)?(HUSKY=0|HUSKY_SKIP_HOOKS=1|SKIP=\S+|LEFTHOOK=0|LEFTHOOK_EXCLUDE=\S+|PRE_COMMIT_ALLOW_NO_CONFIG=1|OVERCOMMIT_DISABLE=1)/

const RUNNER = /\b(?:(?:npm|pnpm|yarn|bun)\s+(?:run\s+)?test|vitest|jest|pytest|py\.test|go\s+test|cargo\s+(?:test|nextest)|mocha|playwright\s+test|rspec|phpunit|dotnet\s+test)\b/

const NARROWING: ReadonlyArray<readonly [string, RegExp]> = [
  ['--testPathIgnorePatterns', /--testPathIgnorePatterns\b/],
  ['--passWithNoTests', /--passWithNoTests\b/],
  ['--deselect', /--deselect\b/],
  ['-k "not …"', /\s-k\s+["']?not\b/],
  ['--ignore', /\s--ignore(?:-glob)?[= ]/],
  ['--exclude', /\s--exclude[= ]/],
  ['--skip', /\s--skip\b/],
  ['-p no:', /\s-p\s+no:/],
]

const SNAPSHOT_UPDATE = /\b(?:jest|vitest|playwright\s+test|(?:npm|pnpm|yarn|bun)\s+(?:run\s+)?test)\b[^;&|]*\s(?:-u|--updateSnapshot|--update-snapshots|--update)\b|--snapshot-update\b|--snapshot-update\b|\binsta\s+accept\b|\bINSTA_UPDATE=always\b|UPDATE_SNAPSHOTS?=(?:1|true)/

const GUARDED_FOR_SHELL = (path: string, testPattern?: RegExp): GoalpostCategory | null => {
  if (isTestFile(path, testPattern) || SNAPSHOT_FILE.test(path)) {
    return 'tests'
  }
  if (CI_FILE.test(path)) {
    return 'ci'
  }
  if (TS_CONFIG.test(path) || LINT_CONFIG.test(path) || PY_CONFIG.test(path)) {
    return 'config'
  }

  return null
}

/**
 * Everything a shell command does to lower the bar: skipping git hooks,
 * deleting tests, narrowing or rewriting what a test run checks, and editing
 * a guarded file where no diff can be seen.
 */
export function inspectCommand(command: string, options: DetectOptions): GoalpostFinding[] {
  const plain = withoutQuoted(command)
  const found: GoalpostFinding[] = []

  const bypass: string[] = []
  for (const verb of ['commit', 'push', 'merge', 'am', 'rebase', 'cherry-pick', 'revert']) {
    for (const [segment] of plain.matchAll(GIT_VERB(verb))) {
      if (/\s--no-verify\b/.test(segment)) {
        bypass.push(`git ${verb} --no-verify`)
      } else if (verb === 'commit' && /\s-[a-zA-Z]*n[a-zA-Z]*(?=\s|$)/.test(segment)) {
        bypass.push('git commit -n')
      }
    }
  }
  const env = SKIP_HOOK_ENV.exec(plain)
  if (env) {
    bypass.push(env[1] ?? 'hook switch')
  }
  if (/\bgit\b[^;&|]*\bconfig\b[^;&|]*\bcore\.hooksPath\b/.test(plain)) {
    bypass.push('git config core.hooksPath')
  }
  if (bypass.length > 0) {
    found.push({
      rule: 'bypass',
      title: `skips the git hooks (${bypass[0]})`,
      detail: 'the checks a commit or push runs are switched off for this one',
      after: [command.slice(0, 200)],
    })
  }

  if (RUNNER.test(plain)) {
    const narrowed = NARROWING.filter(([, pattern]) => pattern.test(command)).map(([name]) => name)
    if (narrowed.length > 0) {
      found.push({
        rule: 'tests.narrowed',
        title: `runs the tests with ${narrowed.join(', ')}`,
        detail: 'a narrowed run can pass while the tests it leaves out fail',
        after: [command.slice(0, 200)],
      })
    }
  }
  if (SNAPSHOT_UPDATE.test(plain)) {
    found.push({
      rule: 'tests.snapshots',
      title: 'rewrites the snapshots',
      detail: 'updating snapshots makes every snapshot test agree with the code as it is now',
      after: [command.slice(0, 200)],
    })
  }

  const deleted: string[] = []
  const edited: Array<readonly [string, GoalpostCategory]> = []
  for (const segment of segmentsOf(command)) {
    const [verb = '', ...rest] = withoutPrefix(segment.words)
    const args = rest.filter(word => !word.startsWith('-'))
    const isDelete = ['rm', 'unlink', 'trash'].includes(verb) || (verb === 'git' && rest[0] === 'rm')
    const isInPlace =
      (['sed', 'gsed'].includes(verb) && rest.some(word => /^-[a-zA-Z]*i/.test(word) || word === '--in-place')) ||
      (verb === 'perl' && rest.some(word => /^-[a-zA-Z]*i/.test(word)))
    if (isDelete) {
      deleted.push(...(verb === 'git' ? args.slice(1) : args).filter(word => isTestFile(word, options.testPattern) || SNAPSHOT_FILE.test(word)))
    }
    const targets = [...(isInPlace ? args : []), ...segment.redirects]
    for (const target of targets) {
      const category = GUARDED_FOR_SHELL(target, options.testPattern)
      if (category !== null) {
        edited.push([target, category] as const)
      }
    }
  }
  if (deleted.length > 0) {
    found.push({
      rule: 'tests.removed',
      file: deleted[0],
      title: `deletes ${deleted.length === 1 ? 'a test file' : plural(deleted.length, 'test file')}`,
      detail: deleted.slice(0, SAMPLE).join(', '),
      before: deleted.slice(0, SAMPLE),
    })
  } else if (edited.length > 0) {
    const [first] = edited
    found.push({
      rule: 'shell-edit',
      file: first?.[0],
      title: `edits ${basename(first?.[0] ?? '')} from the shell`,
      detail: 'a guarded file changed where goalpost-guard cannot see the diff; use Edit so it can',
      after: [command.slice(0, 200)],
      category: first?.[1],
    })
  }

  return found.filter(finding => options.categories.has(finding.category ?? CATEGORY_OF[finding.rule]))
}

export function categoryOf(finding: GoalpostFinding): GoalpostCategory {
  return finding.category ?? CATEGORY_OF[finding.rule]
}

